import{_ as t,o as i,c as s,a0 as a}from"./chunks/framework.B6reNh8h.js";const u=JSON.parse('{"title":"Renderer plugins","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/renderer-plugins.md","filePath":"explanation/renderer-plugins.md"}'),o={name:"explanation/renderer-plugins.md"};function n(d,e,r,l,c,h){return i(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="renderer-plugins" tabindex="-1">Renderer plugins <a class="header-anchor" href="#renderer-plugins" aria-label="Permalink to &quot;Renderer plugins&quot;">​</a></h1><p>Built-in rendering is the floor, not the ceiling. A driver can ship a <strong>renderer plugin</strong> — a claim on ViewNode <em>kinds</em> plus a <code>render</code> op that returns a canonical <code>RenderModel</code> — and pavo routes matching nodes to it instead of interpreting them natively.</p><p>There is no separate plugin ecosystem: plugins are tamias drivers. <code>examples/drivers/viz-graph/</code> claims <code>graph</code> on all three surfaces and renders SVG/ascii the built-ins don&#39;t; its manifest declares <strong>zero views</strong> — it renders other drivers&#39; trees.</p><h2 id="the-two-halves" tabindex="-1">The two halves <a class="header-anchor" href="#the-two-halves" aria-label="Permalink to &quot;The two halves&quot;">​</a></h2><p><strong>Manifest half</strong> — <code>renderers[]</code> declares the claim:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;graph&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;kinds&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;graph&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;priority&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> &quot;surfaces&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   &quot;cli&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;formats&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;svg&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ascii&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]},</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   &quot;tui&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   &quot;web&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;component&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;viz-graph&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;island&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}}</span></span></code></pre></div><p><code>kinds</code> lists ViewNode kinds (or <code>&quot;*&quot;</code> for catch-all); <code>surfaces</code> says where the claim holds and which <code>--format</code> values it takes (empty <code>formats</code> = wildcard). Absent surface = unsupported there.</p><p><strong>Wire half</strong> — the <code>render</code> op:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>→ {&quot;op&quot;:&quot;render&quot;,&quot;kind&quot;:&quot;graph&quot;,&quot;node&quot;:{…ViewNode verbatim…},</span></span>
<span class="line"><span>   &quot;data&quot;:{…view bindings…},&quot;surface&quot;:&quot;cli&quot;,&quot;format&quot;:&quot;svg&quot;}</span></span>
<span class="line"><span>← {&quot;ok&quot;:true,&quot;result&quot;:{&quot;type&quot;:&quot;svg&quot;,&quot;markup&quot;:&quot;&lt;svg&gt;…&quot;}}</span></span></code></pre></div><p><code>node</code> arrives untyped so unknown/future fields survive; <code>data</code> is the same binding map <code>view</code> returns, so the plugin resolves <code>node.query</code> itself.</p><h2 id="claim-resolution" tabindex="-1">Claim resolution <a class="header-anchor" href="#claim-resolution" aria-label="Permalink to &quot;Claim resolution&quot;">​</a></h2><p>Deterministic, same policy as chrome contributions:</p><ol><li>Explicit kinds beat <code>&quot;*&quot;</code>.</li><li>Lower <code>priority</code> wins (default 100).</li><li>Ties break by driver name, then renderer id.</li></ol><p><code>pavo</code>&#39;s <code>RendererRegistry</code> (pavo-core <code>renderers</code> module) folds all manifests into this order once at discovery; <code>/api/renderers</code> on <code>pavo serve</code> exposes the resolved claims to the web surface.</p><h2 id="precedence-over-built-ins" tabindex="-1">Precedence over built-ins <a class="header-anchor" href="#precedence-over-built-ins" aria-label="Permalink to &quot;Precedence over built-ins&quot;">​</a></h2><p>Plugin claims are <strong>canonical per node</strong> on every surface: a node whose kind+surface is claimed renders via <code>render</code> → RenderModel; built-ins are the fallback for unclaimed kinds <em>and</em> for plugin failures. On <code>cli</code> this includes <code>--format</code> names that collide with built-ins — <code>text</code>, <code>dot</code>, and <code>mermaid</code> are claimable via <code>cli.formats</code> (empty = wildcard), and a claim wins for the nodes it covers while unclaimed nodes keep the built-in output. <code>json</code> is the one exception: the raw <code>ViewResult</code> dump is host-owned and never routed to plugins. On <code>web</code> the same rule makes the plugin RenderModel canonical for claimed kinds — <code>GraphIsland.vue</code> is the <code>graph</code> fallback when no plugin claims it (and while the render op is in flight a placeholder shows, never the built-in).</p><h2 id="rendermodel-—-the-canonical-output" tabindex="-1">RenderModel — the canonical output <a class="header-anchor" href="#rendermodel-—-the-canonical-output" aria-label="Permalink to &quot;RenderModel — the canonical output&quot;">​</a></h2><p>Plugins don&#39;t ship surface code; they answer one of four tagged models and each surface maps it natively:</p><table tabindex="0"><thead><tr><th>variant</th><th>CLI</th><th>TUI</th><th>web</th></tr></thead><tbody><tr><td><code>rows</code></td><td>aligned table</td><td>table rows</td><td><code>&lt;table&gt;</code></td></tr><tr><td><code>svg</code></td><td>raw markup</td><td><code>[svg]</code> hint</td><td><code>v-html</code> island</td></tr><tr><td><code>text</code></td><td>lines</td><td>lines</td><td><code>&lt;pre&gt;</code></td></tr><tr><td><code>placeholder</code></td><td><code>[component]</code></td><td>box + detail</td><td>named component</td></tr></tbody></table><p>The set is deliberately small — plugins needing richer output use <code>placeholder</code> (web components) or <code>svg</code> (self-contained markup). <strong>No HTML in RenderModel</strong>: self-contained markup is <code>svg</code> only.</p><h2 id="the-fallback-contract" tabindex="-1">The fallback contract <a class="header-anchor" href="#the-fallback-contract" aria-label="Permalink to &quot;The fallback contract&quot;">​</a></h2><ul><li><strong>Built-ins are not reserved.</strong> A plugin may claim <code>graph</code> (or any kind) and override built-in rendering on the surfaces it declares.</li><li><strong>Fallback is mandatory.</strong> When no plugin claims a kind+surface, or <code>render</code> errors/times out, hosts use the built-in interpretation — unknown kinds still degrade to KV. Plugin failure must never break a view; that&#39;s what makes plugins safe to discover on <code>PATH</code> alongside everything else.</li><li><strong><code>web.component</code> is a hint.</strong> v1 renders every RenderModel generically; <code>component</code>/<code>island</code> name rich mounts for hosts that resolve them (dynamic-imported components are a v2 concern).</li></ul><h2 id="why-plugins-instead-of-embed" tabindex="-1">Why plugins instead of <code>embed</code> <a class="header-anchor" href="#why-plugins-instead-of-embed" aria-label="Permalink to &quot;Why plugins instead of \`embed\`&quot;">​</a></h2><p><code>embed</code> names a component for <em>one node</em>; a renderer plugin claims a <em>kind</em> — every <code>graph</code> node in every view, from every driver. Plugins are how <code>graph</code> itself migrated: the IR keeps the structure, the plugin owns the rendering. <code>table</code>/<code>list</code> plugins are the expected next migrations.</p>`,24)])])}const k=t(o,[["render",n]]);export{u as __pageData,k as default};
